#!/usr/bin/env node
/**
 * Seed synthetic biometric enrollments so a fresh clone demos the whole flow
 * without a camera (capture-stations.md §4 — the "import station").
 *
 *   npm run seed:biometric                      # enroll finger 0 for every employee
 *   npm run seed:biometric -- --fingers 0,1     # two fingers each
 *   npm run seed:biometric -- --punch           # …then punch once per employee
 *   npm run seed:biometric -- --force           # overwrite an existing enrollment
 *
 * NFR-07: the templates are deterministic **synthetic minutiae** generated by the
 * matcher sidecar — no real finger is involved. They are stored with
 * `source: 'imported'` and `station: 'seed'`, so a demo never misrepresents their
 * origin (they are visibly not camera captures in the /biometric admin view).
 *
 * Env: ZK_HTTP_URL (default http://localhost:3000), ZK_MATCHER_URL (default
 * http://127.0.0.1:28090). Both runtimes must be up — `npm run dev:biometric`.
 */

const args = process.argv.slice(2);
const force = args.includes('--force');
const doPunch = args.includes('--punch');
const fingersFlag = args.find((a) => a.startsWith('--fingers='));
const fingers = fingersFlag
  ? fingersFlag.slice('--fingers='.length).split(',').map((n) => Number.parseInt(n, 10))
  : [0];
if (fingers.some((f) => !Number.isInteger(f) || f < 0 || f > 9)) {
  console.error('--fingers must be a comma-separated list of 0-9');
  process.exit(2);
}

const HTTP = process.env.ZK_HTTP_URL ?? 'http://localhost:3000';
const MATCHER = process.env.ZK_MATCHER_URL ?? 'http://127.0.0.1:28090';

async function json(url, init) {
  const res = await fetch(url, init);
  const body = await res.json().catch(() => ({}));
  return { res, body };
}

const post = (path, body) =>
  json(`${HTTP}${path}`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(body),
  });

/** Deterministic synthetic ISO 19794-2 fixture (same generator the tests use). */
async function synthetic(seed, rot = 0, jitter = 0, drop = 0) {
  const { res, body } = await json(`${MATCHER}/synthetic?seed=${seed}&rot=${rot}&jitter=${jitter}&drop=${drop}`);
  if (!res.ok || !body.templateB64) throw new Error(`synthetic fixture failed (seed ${seed})`);
  return body.templateB64;
}

const status = await json(`${HTTP}/api/biometric/status`);
if (status.res.status === 503) {
  console.error('biometric subsystem is disabled — start with ZK_MATCHER_URL set (npm run dev:biometric)');
  process.exit(2);
}
if (!status.body.matcherUp) {
  console.error(`matcher sidecar unreachable at ${MATCHER}`);
  process.exit(2);
}
if (status.body.enrolled > 0 && !force) {
  console.error(`${status.body.enrolled} enrollment(s) already exist — pass --force to overwrite them`);
  process.exit(3);
}

// the statement version this deployment collects consent against: the page, the
// record and this script must all point at the same wording (Phase 8)
const statement = await json(`${HTTP}/api/biometric/consent`);
if (!statement.res.ok) {
  console.error(`cannot read the consent statement (HTTP ${statement.res.status})`);
  process.exit(2);
}

const users = (await json(`${HTTP}/api/users`)).body.users ?? [];
if (!users.length) {
  console.error('no employees in the device store — seed a store or push employees from BITS first');
  process.exit(3);
}

let enrolled = 0;
for (const user of users) {
  for (const finger of fingers) {
    const seed = user.uid * 10 + finger;
    const samples = [
      await synthetic(seed, 0),
      await synthetic(seed, 2, 1, 10),
      await synthetic(seed, -2, 2, 10),
    ];
    const { res, body } = await post('/api/biometric/enroll', {
      userId: user.userId,
      finger,
      consent: true,
      consentVersion: statement.body.version,
      samples,
      source: 'imported',
      station: 'seed',
    });
    if (!res.ok) {
      console.error(`✗ ${user.userId} finger ${finger}: ${body.error ?? res.status}`);
      process.exitCode = 1;
      continue;
    }
    enrolled += 1;
    console.log(`✔ ${user.userId} ${user.name} — finger ${finger}, ${body.samples} consistent samples`);
    if (doPunch) {
      const punch = await post('/api/biometric/punch', { templateB64: await synthetic(seed, 3, 1, 10), station: 'seed' });
      const extra = punch.body.result === 'pass' ? `${punch.body.name} (score ${punch.body.score})` : punch.body.decision;
      console.log(`   punch → ${punch.body.result}: ${extra}`);
    }
  }
}

console.log(
  `\n${enrolled} synthetic enrollment(s) stored (source=imported, station=seed).\n` +
    `These are fixtures, not camera captures — see them at ${HTTP}/biometric.\n` +
    `Clear everything with: curl -X POST ${HTTP}/api/biometric/purge -H "content-type: application/json" -d '{"confirm":true}'`,
);